const body = $input.first().json.body;
const required = ['customer_name', 'customer_email', 'product_or_service'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
return [{ json: {
  valid: true,
  customerId: body.customer_id || `C-${Date.now()}`,
  customerName: body.customer_name.trim(),
  customerEmail: body.customer_email.trim(),
  customerTitle: body.customer_title || '',
  customerCompany: body.customer_company || '',
  productOrService: body.product_or_service.trim(),
  useCase: (body.use_case || '').slice(0, 300),
  successMetric: body.success_metric || '',
  requestedBy: body.requested_by || '',
  submissionUrl: body.submission_url || `${process.env.TESTIMONIAL_FORM_URL || 'https://your-form-url.com'}/testimonial`,
  requestedAt: new Date().toISOString()
} }];

