const body = $input.first().json.body;
const required = ['raw_testimonial', 'customer_name'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
if (body.raw_testimonial.trim().length < 30) return [{ json: { valid: false, error: 'Testimonial too short' } }];
return [{ json: {
  valid: true,
  testimonialId: `T-${Date.now()}`,
  customerId: body.customer_id || '',
  customerName: body.customer_name.trim(),
  customerTitle: body.customer_title || '',
  customerCompany: body.customer_company || '',
  productOrService: body.product_or_service || '',
  rawTestimonial: body.raw_testimonial.trim().slice(0, 2000),
  rating: parseInt(body.rating) || null,
  useCase: body.use_case || '',
  permissionToPublish: body.permission_to_publish !== false,
  preferredPlatforms: Array.isArray(body.preferred_platforms) ? body.preferred_platforms : [],
  submittedAt: new Date().toISOString()
} }];

values.content:
Process this customer testimonial.

Customer: {{ $json.customerName }}{{ $json.customerTitle ? ', ' + $json.customerTitle : '' }}{{ $json.customerCompany ? ' at ' + $json.customerCompany : '' }}
Product/service: {{ $json.productOrService || 'not specified' }}
Use case: {{ $json.useCase || 'not specified' }}
Rating: {{ $json.rating ? $json.rating + '/5' : 'not given' }}
Permission to publish: {{ $json.permissionToPublish }}
Preferred platforms: {{ $json.preferredPlatforms.join(', ') || 'any' }}

Raw testimonial:
{{ $json.rawTestimonial }}

Return this JSON:
{
  "quality_score": 8,
  "quality_notes": "brief assessment — what makes this testimonial strong or weak for marketing use",
  "polished_quote": "clean, publish-ready version — preserve their voice, fix obvious typos/grammar only, do not add claims",
  "short_pull_quote": "15-25 word version for social media or image overlays — the single most impactful sentence",
  "key_outcomes_mentioned": ["specific results or benefits the customer mentioned"],
  "emotion_tags": ["2-4 emotional themes: e.g. relief, confidence, time-saved, trust"],
  "use_case_tags": ["2-3 use case tags for searchable content library"],
  "platform_versions": {
    "website_hero": "1-2 sentence version for homepage or landing page",
    "case_study": "full polished version with context, suitable for a detailed case study page",
    "social_media": "tweet-length version under 240 chars, punchy",
    "sales_deck": "version formatted for a sales presentation slide — concise and impactful"
  },
  "suggested_attribution": "First Last, Title, Company — formatted for display",
  "publish_recommendation": "one of: feature_prominently | use_as_is | minor_edit_needed | needs_clarification | do_not_use",
  "publish_recommendation_note": "why"
}

